function WorkspaceSettingsPage({ businessName, setBusinessName, currency, setCurrency, paymentMethods, setPaymentMethods, defaultSignIn, defaultSignOut, strictSignIn, allowMultipleDailyShifts, setStrictSignIn, setAllowMultipleDailyShifts, categories, setCategories, setDefaultSignIn, setDefaultSignOut, onChange }: any) { const toggleMethod = (method: string) => setPaymentMethods(paymentMethods.includes(method) ? paymentMethods.filter((item: string) => item !== method) : [...paymentMethods, method]); return <><PageHeading eyebrow="WORKSPACE / SETTINGS" title="Settings" subtitle="Control identity, money, attendance, stock, and account access." /><section className="settings-stack"><article className="panel member-form"><PanelHeading title="Business identity and money" subtitle="These choices are used across the workspace and sales records." /><div className="form-grid"><label><span>Business name</span><input value={businessName} onChange={(event) => { setBusinessName(event.target.value); onChange() }} /></label><label><span>Display currency</span><select value={currency} onChange={(event) => { setCurrency(event.target.value); onChange() }}><option>KES</option><option>USD</option><option>EUR</option></select></label></div><div className="settings-choice-group"><strong>Sales payment methods</strong><small>Choose methods available to cashiers.</small><div className="settings-choice-grid">{['Cash', 'Credit', 'Mobile money'].map((method) => <label key={method} className={paymentMethods.includes(method) ? 'settings-choice enabled' : 'settings-choice'}><input type="checkbox" checked={paymentMethods.includes(method)} onChange={() => { toggleMethod(method); onChange() }} /><span>{method}</span></label>)}</div></div></article><article className="panel member-form"><PanelHeading title="Attendance rules" subtitle="Control daily sign-in behavior and new member schedules." /><div className="form-grid settings-times"><label><span>Default sign-in time</span><input type="time" value={defaultSignIn} onChange={(event) => { setDefaultSignIn(event.target.value); onChange() }} /></label><label><span>Default sign-out time</span><input type="time" value={defaultSignOut} onChange={(event) => { setDefaultSignOut(event.target.value); onChange() }} /></label><label className="settings-checkbox"><input type="checkbox" checked={!allowMultipleDailyShifts} onChange={(event) => { setAllowMultipleDailyShifts(!event.target.checked); onChange() }} /><span><strong>One sign-in per day</strong><small>Prevent a second shift on the same day.</small></span></label><label className="settings-checkbox"><input type="checkbox" checked={strictSignIn} onChange={(event) => { setStrictSignIn(event.target.checked); onChange() }} /><span><strong>Strict sign-in checks</strong><small>Apply schedule checks during sign-in.</small></span></label></div></article><article className="panel member-form"><PanelHeading title="Inventory categories" subtitle="Categories available when recording stock." /><label className="settings-wide-field"><span>Categories</span><input value={categories.join(', ')} onChange={(event) => { setCategories(event.target.value.split(',').map((item: string) => item.trim()).filter(Boolean)); onChange() }} /></label></article><article className="panel member-form"><PanelHeading title="Account and access policy" subtitle="Only account-enabled members appear in Permissions and can sign in." /><div className="settings-policy"><span className="settings-policy-icon">✓</span><div><strong>Owner-controlled access</strong><small>Enable accounts from Add member, then assign pages in Permissions.</small></div></div></article></section></> }

import { useEffect, useMemo, useState } from 'react'
import type { FormEvent } from 'react'
import './App.css'

type Role = 'Owner' | 'Manager' | 'Stock Keeper' | 'Cashier' | 'Worker'
type AttendanceStatus = 'Present' | 'Late' | 'Absent' | 'Off'
type PayFrequency = 'Daily' | 'Weekly' | 'Monthly'
type PaymentStatus = 'Pending' | 'Paid' | 'On hold'
type Member = { id: number; tenantId?: string; name: string; username: string; password: string; hasAccount?: boolean; phone: string; email: string; department: string; role: Role; initials: string; color: string; payRate: number; payFrequency: PayFrequency; signInTime: string; signOutTime: string }
type OwnerAccount = { name: string; username: string; password: string; business?: string; tenantId?: string }
type AttendanceEntry = { memberId: number; date: string; status: AttendanceStatus; checkIn: string; checkOut: string; paymentStatus?: PaymentStatus }
type PaymentMethod = 'Cash' | 'Credit' | 'Mobile money'
type Sale = { id: number; amount: number; paymentMethod: PaymentMethod; date: string; time: string; cashier: string }
type InventoryItem = { id: number; name: string; category: string; quantity: number; unit: string; reorderAt: number }
type Deduction = { id: number; memberId: number; amount: number; reason: string; date: string }
type AccessArea = 'Overview' | 'Attendance' | 'Payroll' | 'Deductions' | 'Departments' | 'Inventory' | 'Sales' | 'Team' | 'OFF MARK' | 'ROLL' | 'Settings'
type SubscriptionPlan = 'Starter' | 'Growth' | 'Scale'
type SubscriptionStatus = 'Trial' | 'Active' | 'Paused' | 'Canceled'
type BusinessAccount = {
  id: number
  businessName: string
  ownerName: string
  email: string
  username: string
  password: string
  industry: string
  plan: SubscriptionPlan
  status: SubscriptionStatus
  seats: number
  monthlyPrice: number
  nextBilling: string
  createdAt: string
  tenantId: string
}

const roles: Role[] = ['Owner', 'Manager', 'Stock Keeper', 'Cashier', 'Worker']
const uniqueAccessAreas: AccessArea[] = ['Overview', 'Attendance', 'Payroll', 'Deductions', 'Departments', 'Inventory', 'Sales', 'Team', 'OFF MARK', 'ROLL', 'Settings']
const accessAreas: AccessArea[] = Array.from(new Set(uniqueAccessAreas)) as AccessArea[]
const navItems = [{ label: 'Overview', icon: '◈' }, { label: 'Sales', icon: '↗' }, { label: 'Attendance', icon: '◷' }, { label: 'Payroll', icon: 'KES' }, { label: 'Deductions', icon: '−' }, { label: 'Departments', icon: '▦' }, { label: 'Inventory', icon: '□' }, { label: 'OFF MARK', icon: '◉' }]
const sidebarLinks = Array.from(new Set([...navItems.map((item) => item.label), 'Team', 'Add member', 'Permissions', 'ROLL', 'OFF MARK', 'Settings']))
const today = new Date().toISOString().slice(0, 10)
const planPrices: Record<SubscriptionPlan, number> = { Starter: 29, Growth: 79, Scale: 149 }
const defaultBusinessAccounts: BusinessAccount[] = [
  { id: 1, businessName: 'Sierra Bistro', ownerName: 'Aisha Musa', email: 'aisha@sierra-bistro.com', username: 'aisha', password: 'admin123', industry: 'Hospitality', plan: 'Growth', status: 'Active', seats: 18, monthlyPrice: planPrices.Growth, nextBilling: '2026-10-12', createdAt: '2026-08-15', tenantId: 'tenant-sierra' },
  { id: 2, businessName: 'Summit Retail', ownerName: 'Kevin Tate', email: 'kevin@summit-retail.com', username: 'kevin', password: 'admin123', industry: 'Retail', plan: 'Starter', status: 'Trial', seats: 6, monthlyPrice: planPrices.Starter, nextBilling: '2026-09-28', createdAt: '2026-09-10', tenantId: 'tenant-summit' },
  { id: 3, businessName: 'Harbor Build', ownerName: 'Lina Brooks', email: 'lina@harborbuild.co', username: 'lina', password: 'admin123', industry: 'Construction', plan: 'Scale', status: 'Paused', seats: 32, monthlyPrice: planPrices.Scale, nextBilling: '2026-10-03', createdAt: '2026-07-01', tenantId: 'tenant-harbor' },
]
const pagePaths: Record<string, string> = { Welcome: '/', Register: '/register/', 'Sign in': '/signin/', Admin: '/admin/', 'Admin sign in': '/admin-signin/', 'Business accounts': '/admin/businesses/', 'Create business account': '/admin/create/', 'Subscriptions': '/admin/subscriptions/', 'Platform settings': '/admin/settings/', Overview: '/dashboard/', Sales: '/sales/', Attendance: '/attendance/', Payroll: '/payee/', Deductions: '/deductions/', Departments: '/department/', Inventory: '/store/', Team: '/team/', 'Add member': '/add/', 'Add department': '/department/add/', Permissions: '/permit/', Settings: '/settings/', 'OFF MARK': '/offmark/', ROLL: '/roll/', 'Worker sign-in': '/worker-signin/', 'Worker checkout': '/signout/' }
const pathPages: Record<string, string> = Object.fromEntries(Object.entries(pagePaths).map(([page, path]) => [path, page]))
const defaultSiteAdminAccount: OwnerAccount = { name: 'Platform admin', username: 'admin', password: 'admin@123', business: 'Biz Track HQ' }
const pageForPath = (path: string) => {
  const cleaned = (path || '/').replace(/\/$/, '') || '/'
  if (cleaned === '/' || cleaned === '/welcome' || cleaned === '/signin' || cleaned === '/register') return cleaned === '/signin' ? 'Sign in' : cleaned === '/register' ? 'Register' : 'Welcome'
  return pathPages[cleaned] || pathPages[cleaned + '/'] || 'Welcome'
}
function readStored<T>(key: string, fallback: T): T { try { return JSON.parse(localStorage.getItem(key) || '') as T } catch { return fallback } }
function ensureSiteAdminAccount(): OwnerAccount {
  const stored = readStored<OwnerAccount | null>('biztrack-site-admin', null)
  const account = stored && stored.username && stored.password ? stored : defaultSiteAdminAccount
  localStorage.setItem('biztrack-site-admin', JSON.stringify(account))
  if (localStorage.getItem('biztrack-site-admin-session') !== 'true') localStorage.setItem('biztrack-site-admin-session', 'false')
  return account
}
function initialsFor(name: string) { return name.split(' ').filter(Boolean).slice(0, 2).map((part) => part[0].toUpperCase()).join('') }
function normalizeMember(member: Partial<Member>, index: number, tenantId = 'workspace'): Member { const name = member.name || 'Unnamed member'; return { ...member, tenantId: member.tenantId || tenantId, id: member.id || Date.now() + index, name, username: member.username || name.toLowerCase().replace(/[^a-z0-9]+/g, '.').replace(/^\.|\.$/g, ''), password: member.password || '', hasAccount: member.hasAccount === true, phone: member.phone || 'NA', email: member.email || 'NA', department: member.department || 'Unassigned', role: member.role || 'Worker', initials: member.initials || initialsFor(name), color: member.color || 'mint', payRate: member.payRate || 1000, payFrequency: member.payFrequency || 'Daily', signInTime: member.signInTime || '08:00', signOutTime: member.signOutTime || '17:00' } as Member }
const emptyAccess: Record<number, AccessArea[]> = {}

function App() {
  const [activeNav, setActiveNav] = useState(() => pageForPath(window.location.pathname))
  const [role, setRole] = useState<Role>('Owner')
    const [isOnline, setIsOnline] = useState(false)
    const [lastSynced, setLastSynced] = useState('2 min ago')
    const [pendingChanges, setPendingChanges] = useState(2)
    const [attendanceNotice, setAttendanceNotice] = useState('')
    const [ownerAccount, setOwnerAccount] = useState<OwnerAccount | null>(() => readStored<OwnerAccount | null>('fielddesk-owner', null))
    const [siteAdminAccount, setSiteAdminAccount] = useState<OwnerAccount | null>(() => ensureSiteAdminAccount())
    const [siteAdminSession, setSiteAdminSession] = useState(() => localStorage.getItem('biztrack-site-admin-session') === 'true')
    const [businessAccounts, setBusinessAccounts] = useState<BusinessAccount[]>(() => readStored<BusinessAccount[]>('biztrack-business-accounts', defaultBusinessAccounts))
    const tenantId = ownerAccount?.tenantId || 'workspace'
    const tenantKey = (name: string) => `biztrack-${tenantId}-${name}`
    const [members, setMembers] = useState<Member[]>(() => readStored<Partial<Member>[]>(tenantKey('members'), []).map((member, index) => normalizeMember(member, index, tenantId)))
    const [departmentList, setDepartmentList] = useState<string[]>(() => readStored(tenantKey('departments'), []))
    const [attendance, setAttendance] = useState<AttendanceEntry[]>(() => readStored(tenantKey('attendance-log'), []))
    const [sales, setSales] = useState<Sale[]>(() => readStored(tenantKey('sales'), []))
    const [salesHistory, setSalesHistory] = useState<Sale[]>(() => readStored(tenantKey('sales-history'), []))
    const [deductions, setDeductions] = useState<Deduction[]>(() => readStored(tenantKey('deductions'), []))
    const [inventory, setInventory] = useState<InventoryItem[]>(() => readStored(tenantKey('inventory'), []))
    const [storeCategories, setStoreCategories] = useState<string[]>(() => readStored(tenantKey('store-categories'), []))
    const [workspaceName, setWorkspaceName] = useState(() => ownerAccount?.business || '')
    const [currency, setCurrency] = useState(() => localStorage.getItem(tenantKey('currency')) || 'KES')
    const [paymentMethods, setPaymentMethods] = useState<string[]>(() => readStored(tenantKey('payment-methods'), ['Cash', 'Credit', 'Mobile money']))
  const [strictSignIn, setStrictSignIn] = useState(() => localStorage.getItem(tenantKey('strict-sign-in')) === 'true')
  const [allowMultipleDailyShifts, setAllowMultipleDailyShifts] = useState(() => localStorage.getItem(tenantKey('multiple-daily-shifts')) === 'true')
  const [defaultSignIn, setDefaultSignIn] = useState(() => localStorage.getItem(tenantKey('default-sign-in')) || '08:00')
  const [defaultSignOut, setDefaultSignOut] = useState(() => localStorage.getItem(tenantKey('default-sign-out')) || '17:00')
  const [isCheckedIn, setIsCheckedIn] = useState(true)
    const [sessionMemberId, setSessionMemberId] = useState(() => Number(localStorage.getItem(tenantKey('session-member'))) || 0)
  const [accessByMember, setAccessByMember] = useState<Record<number, AccessArea[]>>(() => readStored(tenantKey('access'), emptyAccess))
    const [loadedTenantId, setLoadedTenantId] = useState(tenantId)

  useEffect(() => {
    const handleOnline = () => { setIsOnline(true); setLastSynced('just now'); setPendingChanges(0) }
    const handleOffline = () => setIsOnline(false)
    window.addEventListener('online', handleOnline); window.addEventListener('offline', handleOffline)
    return () => { window.removeEventListener('online', handleOnline); window.removeEventListener('offline', handleOffline) }
  }, [])
  useEffect(() => {
    if (!attendanceNotice) return
    const notice = document.createElement('div')
    notice.className = 'attendance-success'
    notice.textContent = attendanceNotice
    document.body.appendChild(notice)
    return () => notice.remove()
  }, [attendanceNotice])
  useEffect(() => {
    if (loadedTenantId === tenantId) return
    const load = <T,>(name: string, fallback: T) => readStored(tenantKey(name), fallback)
    setMembers(load<Partial<Member>[]>('members', []).map((member, index) => normalizeMember(member, index, tenantId)))
    setDepartmentList(load('departments', []))
    setAttendance(load('attendance-log', []))
    setSales(load('sales', []))
    setSalesHistory(load('sales-history', []))
    setDeductions(load('deductions', []))
    setInventory(load('inventory', []))
    setStoreCategories(load('store-categories', []))
    setWorkspaceName(load('workspace-name', ownerAccount?.business || ''))
    setCurrency(load('currency', 'KES'))
    setPaymentMethods(load('payment-methods', ['Cash', 'Credit', 'Mobile money']))
    setStrictSignIn(localStorage.getItem(tenantKey('strict-sign-in')) === 'true')
    setAllowMultipleDailyShifts(localStorage.getItem(tenantKey('multiple-daily-shifts')) === 'true')
    setDefaultSignIn(localStorage.getItem(tenantKey('default-sign-in')) || '08:00')
    setDefaultSignOut(localStorage.getItem(tenantKey('default-sign-out')) || '17:00')
    setSessionMemberId(Number(localStorage.getItem(tenantKey('session-member'))) || 0)
    setAccessByMember(load('access', emptyAccess))
    setLoadedTenantId(tenantId)
  }, [tenantId])
  useEffect(() => {
    if (loadedTenantId !== tenantId) return
    localStorage.setItem(tenantKey('members'), JSON.stringify(members)); localStorage.setItem(tenantKey('departments'), JSON.stringify(departmentList)); localStorage.setItem(tenantKey('attendance-log'), JSON.stringify(attendance)); localStorage.setItem(tenantKey('sales'), JSON.stringify(sales)); localStorage.setItem(tenantKey('sales-history'), JSON.stringify(salesHistory)); localStorage.setItem(tenantKey('deductions'), JSON.stringify(deductions)); localStorage.setItem(tenantKey('inventory'), JSON.stringify(inventory)); localStorage.setItem(tenantKey('store-categories'), JSON.stringify(storeCategories)); localStorage.setItem(tenantKey('workspace-name'), workspaceName); localStorage.setItem(tenantKey('currency'), currency); localStorage.setItem(tenantKey('payment-methods'), JSON.stringify(paymentMethods)); localStorage.setItem(tenantKey('default-sign-in'), defaultSignIn); localStorage.setItem(tenantKey('default-sign-out'), defaultSignOut); localStorage.setItem(tenantKey('strict-sign-in'), String(strictSignIn)); localStorage.setItem(tenantKey('multiple-daily-shifts'), String(allowMultipleDailyShifts)); localStorage.setItem(tenantKey('role'), role); localStorage.setItem(tenantKey('session-member'), String(sessionMemberId)); localStorage.setItem(tenantKey('access'), JSON.stringify(accessByMember)); if (ownerAccount) localStorage.setItem('fielddesk-owner', JSON.stringify({ ...ownerAccount, business: workspaceName || ownerAccount.business }))
    localStorage.setItem('biztrack-site-admin', JSON.stringify(siteAdminAccount))
    localStorage.setItem('biztrack-site-admin-session', String(siteAdminSession))
    localStorage.setItem('biztrack-business-accounts', JSON.stringify(businessAccounts))
  }, [members, departmentList, attendance, sales, salesHistory, deductions, inventory, storeCategories, workspaceName, currency, paymentMethods, defaultSignIn, defaultSignOut, strictSignIn, allowMultipleDailyShifts, role, sessionMemberId, accessByMember, ownerAccount, tenantId, loadedTenantId, siteAdminAccount, siteAdminSession, businessAccounts])

  const todayAttendance = useMemo(() => members.map((member) => attendance.find((entry) => entry.memberId === member.id && entry.date === today) || { memberId: member.id, date: today, status: 'Absent' as AttendanceStatus, checkIn: '—', checkOut: '—' }), [members, attendance])
  const syncLabel = isOnline ? `Synced ${lastSynced}` : `${pendingChanges} changes waiting to sync`
  const markChanged = () => { if (!isOnline) setPendingChanges((current) => current + 1); else setLastSynced('just now') }
  useEffect(() => {
    const handlePopState = () => setActiveNav(pageForPath(window.location.pathname))
    window.addEventListener('popstate', handlePopState)
    return () => window.removeEventListener('popstate', handlePopState)
  }, [])
  const navigate = (page: string) => {
    const path = pagePaths[page] || '/'
    window.history.pushState({}, '', path)
    setActiveNav(page)
  }
  const currentMember = members[0]
  const toggleCurrentAttendance = () => {
    const existing = attendance.find((entry) => entry.memberId === currentMember?.id && entry.date === today)
    if (!currentMember) return
    if (existing?.status === 'Off') {
      showAttendanceNotice(`${currentMember.name} is marked off for today.`)
      return
    }
    if (isCheckedIn) {
      setAttendance((current) => current.map((entry) => entry.memberId === currentMember.id && entry.date === today ? { ...entry, checkOut: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }) } : entry))
    } else {
      const entry = { memberId: currentMember.id, date: today, status: 'Present' as AttendanceStatus, checkIn: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }), checkOut: '—' }
      setAttendance((current) => existing ? current.map((item) => item.memberId === currentMember.id && item.date === today ? entry : item) : [...current, entry])
    }
    setIsCheckedIn(!isCheckedIn); markChanged()
  }
  const hasAttendanceForToday = (memberId: number) => attendance.some((entry) => entry.memberId === memberId && entry.date === today && (entry.checkIn !== '—' || entry.status === 'Present' || entry.status === 'Late' || entry.checkOut !== '—'))
  const markMemberAttendance = (memberId: number, status: 'Present' | 'Absent') => {
    const member = members.find((person) => person.id === memberId)
    const existing = attendance.find((entry) => entry.memberId === memberId && entry.date === today)
    if (existing?.status === 'Off') {
      showAttendanceNotice(`${member?.name || 'This worker'} is marked off for today.`)
      return false
    }
    const isAlreadySignedIn = Boolean(existing && (existing.status === 'Present' || existing.status === 'Late' || existing.checkOut !== '—'))
    if (status === 'Present') {
      if (!allowMultipleDailyShifts && isAlreadySignedIn) {
        showAttendanceNotice(`${member?.name || 'This worker'} has already signed in for today.`)
        return false
      }
      const existingStatus = existing?.status ?? 'Absent'
      if (!allowMultipleDailyShifts && hasAttendanceForToday(memberId) && (!existing || existingStatus === 'Absent' || existingStatus === 'Off')) {
        showAttendanceNotice(`${member?.name || 'This worker'} has already signed in for today.`)
        return false
      }
    }
    if (status === 'Absent') {
      if (existing && (existing.status === 'Present' || existing.status === 'Late' || existing.checkOut !== '—')) {
        showAttendanceNotice(`${member?.name || 'This worker'} has already signed in for today.`)
        return false
      }
    }
    const nextEntry = {
      memberId,
      date: today,
      status: status === 'Present' ? 'Present' as AttendanceStatus : 'Absent' as AttendanceStatus,
      checkIn: status === 'Present' ? new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }) : '—',
      checkOut: '—',
    }
    setAttendance((current) => existing ? current.map((entry) => entry.memberId === memberId && entry.date === today ? nextEntry : entry) : [...current, nextEntry])
    markChanged()
    return status === 'Present'
  }
  const markMemberSignOut = (memberId: number) => {
    const member = members.find((person) => person.id === memberId)
    const entry = attendance.find((item) => item.memberId === memberId && item.date === today)
    if (!entry || entry.status === 'Off' || entry.status === 'Absent' || entry.checkIn === '—') {
      showAttendanceNotice(`${member?.name || 'This worker'} has already signed out for today.`)
      return false
    }
    if (entry.checkOut !== '—') {
      showAttendanceNotice(`${member?.name || 'This worker'} has already signed out for today.`)
      return false
    }
    if (!allowMultipleDailyShifts && (entry.status === 'Present' || entry.status === 'Late') && entry.checkOut !== '—') {
      showAttendanceNotice(`${member?.name || 'This worker'} has already signed out for today.`)
      return false
    }
    const checkOut = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
    setAttendance((current) => current.map((item) => item.memberId === memberId && item.date === today ? { ...item, checkOut } : item))
    markChanged()
    if (!(window as any).__bulkAttendanceInProgress) showAttendanceNotice(`${member?.name || 'This worker'} signed out successfully`)
    return true
  }
  const createBusinessAccount = (account: { businessName: string; ownerName: string; email: string; username: string; password: string; industry: string; plan: SubscriptionPlan }) => {
    const nextAccount: BusinessAccount = {
      id: Date.now(),
      businessName: account.businessName.trim(),
      ownerName: account.ownerName.trim(),
      email: account.email.trim(),
      username: account.username.trim(),
      password: account.password,
      industry: account.industry,
      plan: account.plan,
      status: 'Trial',
      seats: account.plan === 'Scale' ? 30 : account.plan === 'Growth' ? 12 : 5,
      monthlyPrice: planPrices[account.plan],
      nextBilling: new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString().slice(0, 10),
      createdAt: today,
      tenantId: `tenant-${Date.now()}`,
    }
    setBusinessAccounts((current) => [nextAccount, ...current])
    setOwnerAccount({ name: account.ownerName.trim(), username: account.username.trim(), password: account.password, business: account.businessName.trim(), tenantId: nextAccount.tenantId })
    setWorkspaceName(account.businessName.trim())
    setActiveNav('Overview')
    return nextAccount
  }
  const updateSubscription = (accountId: number, updates: Partial<Pick<BusinessAccount, 'status' | 'plan' | 'seats' | 'nextBilling'>>) => {
    setBusinessAccounts((current) => current.map((account) => account.id === accountId ? { ...account, ...updates, monthlyPrice: updates.plan ? planPrices[updates.plan] : account.monthlyPrice } : account))
  }
  const showAttendanceNotice = (message: string) => {
    setAttendanceNotice(message)
    window.setTimeout(() => setAttendanceNotice(''), 3000)
    navigate('Attendance')
  }
  useEffect(() => { (window as any).__attendanceSuccess = (message: string) => showAttendanceNotice(message); return () => { delete (window as any).__attendanceSuccess } }, [attendanceNotice])
  const updatePayrollStatus = (memberIds: number[], startDate: string, endDate: string, paymentStatus: PaymentStatus) => {
    setAttendance((current) => current.map((entry) => memberIds.includes(entry.memberId) && entry.checkOut !== '—' && entry.date >= startDate && entry.date <= endDate ? { ...entry, paymentStatus } : entry))
    markChanged()
  }
  useEffect(() => { (window as any).__biztrackUpdatePayrollStatus = updatePayrollStatus }, [attendance])
  const login = (memberId: number) => { setSessionMemberId(memberId); navigate('Overview') }
  const logout = () => {
    setSessionMemberId(0)
    window.history.replaceState({}, '', pagePaths['Sign in'])
    setActiveNav('Sign in')
  }
  const canAccess = (page: string) => sessionMemberId === -1 || accessByMember[sessionMemberId]?.includes(page as AccessArea) || (page === 'ROLL' && accessByMember[sessionMemberId]?.includes('Worker sign-in' as AccessArea)) || page === 'Login'
  const dashboardName = sessionMemberId === -1 ? ownerAccount?.name || 'Owner' : members.find((member) => member.id === sessionMemberId)?.name || 'Member'
  const businessName = workspaceName || ownerAccount?.business || 'Your workspace'
  useEffect(() => {
    document.title = sessionMemberId !== 0 && ownerAccount?.business ? ownerAccount.business : 'BizTrack'
  }, [ownerAccount?.business, sessionMemberId])
  useEffect(() => {
    document.querySelectorAll('.app-shell .workspace-switcher strong, .app-shell .brand > span:last-child').forEach((element) => { element.textContent = businessName })
    const workspaceDot = document.querySelector('.app-shell .workspace-dot')
    if (workspaceDot) workspaceDot.textContent = businessName.charAt(0).toUpperCase()
  }, [businessName, activeNav])
  useEffect(() => {
    const profile = document.querySelector('.profile-menu')
    const name = profile?.querySelector('strong')
    const roleLabel = profile?.querySelector('small')
    const avatar = profile?.querySelector('.avatar')
    if (name) name.textContent = dashboardName
    if (roleLabel) roleLabel.textContent = sessionMemberId === -1 ? 'Owner' : members.find((member) => member.id === sessionMemberId)?.role || role
    if (avatar) avatar.textContent = initialsFor(dashboardName)
  }, [dashboardName, sessionMemberId, members, role])
  useEffect(() => {
    if (activeNav !== 'Overview') return
    const updateDashboardHeading = () => {
      const heading = document.querySelector('.page-heading h1')
      const eyebrow = document.querySelector('.page-heading .eyebrow')
      const payrollValue = document.querySelector('.metric-grid .accent-yellow strong')
      const now = new Date()
      if (heading) heading.textContent = `Good morning, ${dashboardName} ✦`
      if (eyebrow) eyebrow.textContent = `${now.toLocaleDateString(undefined, { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' })} · ${now.toLocaleTimeString(undefined, { hour: '2-digit', minute: '2-digit' })}`
      if (payrollValue) payrollValue.textContent = 'KES 1.84m'
    }
    updateDashboardHeading()
    const timer = window.setInterval(updateDashboardHeading, 60000)
    return () => window.clearInterval(timer)
  }, [activeNav, dashboardName])
  /*
    <main className="main-content"><header className="topbar"><div className="breadcrumbs"><span>Workspace</span><b>/</b><strong>{activeNav}</strong></div><div className="top-actions"><div className={`sync-status ${isOnline ? 'online' : 'offline'}`}><span className="status-dot"></span>{syncLabel}</div><button className="icon-button" aria-label="Notifications">♧<span className="notification-dot"></span></button><div className="profile-menu"><div className="avatar avatar-olive">KA</div><span><strong>{sessionMemberId === 0 ? 'Kemi A.' : members.find((member) => member.id === sessionMemberId)?.name || 'Worker'}</strong><small>{sessionMemberId === 0 ? role : 'Worker'}</small></span><button className="text-button" onClick={logout}>Log out</button></div></div></header><div className="page-content">{activeNav === 'Login' ? <LoginPage members={members} onLogin={login} /> : !canAccess(activeNav) ? <AccessDeniedPage onBack={() => navigate('Overview')} /> : activeNav === 'Attendance' ? <AttendancePage members={members} entries={todayAttendance} /> : activeNav === 'Departments' ? <DepartmentsPage departments={departmentList} members={members} onAdd={() => navigate('Add department')} onDelete={deleteDepartment} /> : activeNav === 'Add department' ? <AddDepartmentPage onSubmit={addDepartment} onCancel={() => navigate('Departments')} /> : activeNav === 'Add member' ? <AddMemberPage departments={departmentList} defaultSignIn={defaultSignIn} defaultSignOut={defaultSignOut} onSubmit={addMember} onCancel={() => navigate('Team')} /> : activeNav === 'Team' ? <TeamPage members={members} onAdd={() => navigate('Add member')} onDelete={deleteMember} /> : activeNav === 'Payroll' ? <PayrollPage members={members} attendance={attendance} /> : activeNav === 'Sales' ? <SalesPage sales={sales} salesHistory={salesHistory} onAdd={addSale} onReset={resetSales} /> : activeNav === 'Inventory' ? <InventoryPage inventory={inventory} categories={storeCategories} onAdd={addInventoryItem} onAdjust={updateInventoryQuantity} /> : activeNav === 'Settings' ? <SettingsPage members={members} defaultSignIn={defaultSignIn} defaultSignOut={defaultSignOut} strictSignIn={strictSignIn} setStrictSignIn={setStrictSignIn} categories={storeCategories} setCategories={setStoreCategories} setDefaultSignIn={setDefaultSignIn} setDefaultSignOut={setDefaultSignOut} setMembers={setMembers} onChange={markChanged} /> : activeNav === 'Worker sign-in' ? <WorkerSignInPage members={members} entries={attendance} strictSignIn={strictSignIn} defaultSignIn={defaultSignIn} onAttendance={toggleCurrentAttendance} onMarkAttendance={markMemberAttendance} onMarkSignOut={markMemberSignOut} /> : <OverviewPage role={role} setRole={setRole} members={members} isCheckedIn={isCheckedIn} setIsCheckedIn={toggleCurrentAttendance} isOnline={isOnline} onAttendance={() => navigate('Attendance')} />}</div></main>
  */
  const addMember = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault()
    const form = new FormData(event.currentTarget)
    const name = String(form.get('fullName') || '').trim(); const phone = String(form.get('phone') || '').trim(); const email = String(form.get('email') || '').trim() || 'NA'; const department = String(form.get('department') || departmentList[0])
    if (!name || !phone || !department) return
    const payRate = Number(form.get('payRate') || 0)
    const payFrequency = String(form.get('payFrequency') || 'Daily') as PayFrequency
    const signInTime = String(form.get('signInTime') || defaultSignIn)
    const signOutTime = String(form.get('signOutTime') || defaultSignOut)
    const hasAccount = form.get('hasAccount') === 'on'
    const username = String(form.get('username') || '').trim()
    const password = String(form.get('password') || '')
    if (hasAccount && (!username || password.length < 6)) return
    setMembers((current) => [...current, { id: Date.now(), tenantId, name, username, password, hasAccount, phone, email, department, role: 'Worker', initials: initialsFor(name), color: 'mint', payRate, payFrequency, signInTime, signOutTime }])
    markChanged(); event.currentTarget.reset(); navigate('Team')
  }
  const addDepartment = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault()
    const name = String(new FormData(event.currentTarget).get('departmentName') || '').trim()
    if (!name || departmentList.some((department) => department.toLowerCase() === name.toLowerCase())) return
    setDepartmentList((current) => [...current, name]); markChanged(); event.currentTarget.reset(); navigate('Departments')
  }
  const deleteDepartment = (name: string) => {
    if (!window.confirm(`Delete the ${name} department?`)) return
    setDepartmentList((current) => current.filter((department) => department !== name)); markChanged()
  }
  const addSale = (sale: Sale) => { const now = new Date(); setSales((current) => [...current, { ...sale, cashier: dashboardName, date: now.toISOString().slice(0, 10), time: now.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' }) }]); markChanged() }
  const addDeduction = (deduction: Deduction) => { setDeductions((current) => [deduction, ...current]); markChanged() }
  const deleteDeduction = (id: number) => { if (!window.confirm('Remove this deduction?')) return; setDeductions((current) => current.filter((deduction) => deduction.id !== id)); markChanged() }
  const resetSales = () => { if (!window.confirm('Reset current sales? The dated history will be kept.')) return; setSalesHistory((current) => [...current, ...sales]); setSales([]); markChanged() }
  const addInventoryItem = (item: InventoryItem) => { setInventory((current) => [...current, item]); markChanged() }
  const updateInventoryQuantity = (id: number, amount: number) => { setInventory((current) => current.map((item) => item.id === id ? { ...item, quantity: Math.max(0, item.quantity + amount) } : item)); markChanged() }
  const deleteMember = (id: number) => {
    const member = members.find((item) => item.id === id)
    if (!member || !window.confirm(`Delete ${member.name} from the team?`)) return
    setMembers((current) => current.filter((item) => item.id !== id)); markChanged()
  }
  if (activeNav === 'Admin sign in') return <SignInPage ownerAccount={ownerAccount} members={members.filter((member) => member.tenantId === tenantId && member.hasAccount)} siteAdminAccount={siteAdminAccount} onLogin={login} onAdminLogin={(success) => { if (success) { setSiteAdminSession(true); navigate('Admin') } }} onNavigate={navigate} />
  if (activeNav === 'Admin') return <AdminDashboardPage accounts={businessAccounts} onCreate={() => navigate('Create business account')} onViewBusinessAccounts={() => navigate('Business accounts')} onViewSubscriptions={() => navigate('Subscriptions')} onOpenSettings={() => navigate('Platform settings')} onSignOut={() => { setSiteAdminSession(false); navigate('Welcome') }} />
  if (activeNav === 'Create business account') return <CreateBusinessAccountPage onCreate={(account) => { createBusinessAccount(account); setSiteAdminSession(true); navigate('Business accounts') }} onBack={() => navigate('Admin')} />
  if (activeNav === 'Business accounts') return <BusinessAccountsPage accounts={businessAccounts} onBack={() => navigate('Admin')} onCreate={() => navigate('Create business account')} />
  if (activeNav === 'Subscriptions') return <SubscriptionPage accounts={businessAccounts} onUpdate={updateSubscription} onBack={() => navigate('Admin')} />
  if (activeNav === 'Platform settings') return <PlatformSettingsPage onBack={() => navigate('Admin')} onSave={() => navigate('Admin')} />
  if (activeNav === 'Welcome') return <WelcomePage onNavigate={navigate} hasOwnerAccount={Boolean(ownerAccount)} businessName={businessName} />
  if (activeNav === 'Register') return <RegisterPage onNavigate={navigate} onComplete={(account) => { setOwnerAccount({ ...account, tenantId: `tenant-${Date.now()}` }); navigate('Sign in') }} />
  if (activeNav === 'Sign in') return <SignInPage ownerAccount={ownerAccount} members={members.filter((member) => member.tenantId === tenantId && member.hasAccount)} siteAdminAccount={siteAdminAccount} onLogin={login} onAdminLogin={(success) => { if (success) { setSiteAdminSession(true); navigate('Admin') } }} onNavigate={navigate} />
  if (siteAdminSession && !ownerAccount) return <AdminDashboardPage accounts={businessAccounts} onCreate={() => navigate('Create business account')} onViewBusinessAccounts={() => navigate('Business accounts')} onViewSubscriptions={() => navigate('Subscriptions')} onOpenSettings={() => navigate('Platform settings')} onSignOut={() => { setSiteAdminSession(false); navigate('Welcome') }} />
  if (!ownerAccount) return <WelcomePage onNavigate={navigate} hasOwnerAccount={false} businessName={businessName} />
  if (sessionMemberId === 0) return <SignInPage ownerAccount={ownerAccount} members={members.filter((member) => member.tenantId === tenantId && member.hasAccount)} onLogin={login} />
  if (!canAccess(activeNav)) return <AccessDeniedPage onBack={() => navigate('Overview')} />
  if (activeNav === 'Permissions') return <div className="app-shell"><WorkspaceSidebar businessName={businessName} activeNav={activeNav} onNavigate={navigate} onLogout={logout} /><main className="main-content"><header className="topbar"><div className="breadcrumbs"><span>{businessName}</span><b>/</b><strong>Permissions</strong></div></header><div className="page-content"><PermissionsPage members={members} accessByMember={accessByMember} setAccessByMember={setAccessByMember} onAddMember={() => navigate('Add member')} /></div></main></div>

  if (activeNav === 'OFF MARK') return <div className="app-shell"><WorkspaceSidebar businessName={businessName} activeNav={activeNav} onNavigate={navigate} onLogout={logout} /><main className="main-content"><header className="topbar"><div className="breadcrumbs"><span>{businessName}</span><b>/</b><strong>OFF MARK</strong></div></header><div className="page-content"><OffMarkPage members={members} attendance={attendance} onMark={(memberIds, dates) => { setAttendance((current) => { const next = [...current]; memberIds.forEach((memberId) => dates.forEach((date) => { const existingIndex = next.findIndex((entry) => entry.memberId === memberId && entry.date === date); const entry = { memberId, date, status: 'Off' as AttendanceStatus, checkIn: '—', checkOut: '—' }; if (existingIndex >= 0) next[existingIndex] = { ...next[existingIndex], ...entry }; else next.push(entry) })); return next }); markChanged() }} /></div></main></div>

  if (activeNav === 'Settings') return <div className="app-shell"><WorkspaceSidebar businessName={businessName} activeNav={activeNav} onNavigate={navigate} onLogout={logout} /><main className="main-content"><header className="topbar"><div className="breadcrumbs"><span>{businessName}</span><b>/</b><strong>Settings</strong></div></header><div className="page-content"><WorkspaceSettingsPage businessName={workspaceName} setBusinessName={setWorkspaceName} currency={currency} setCurrency={setCurrency} paymentMethods={paymentMethods} setPaymentMethods={setPaymentMethods} members={members} defaultSignIn={defaultSignIn} defaultSignOut={defaultSignOut} strictSignIn={strictSignIn} allowMultipleDailyShifts={allowMultipleDailyShifts} setStrictSignIn={setStrictSignIn} setAllowMultipleDailyShifts={setAllowMultipleDailyShifts} categories={storeCategories} setCategories={setStoreCategories} setDefaultSignIn={setDefaultSignIn} setDefaultSignOut={setDefaultSignOut} setMembers={setMembers} onChange={() => markChanged()} /></div></main></div>

  if (activeNav === 'Worker sign-in') return <div className="app-shell"><WorkspaceSidebar businessName={businessName} activeNav={activeNav} onNavigate={navigate} onLogout={logout} /><main className="main-content"><header className="topbar"><div className="breadcrumbs"><span>{businessName}</span><b>/</b><strong>Worker sign-in</strong></div></header><div className="page-content"><WorkerSignInPage members={members} entries={attendance} strictSignIn={strictSignIn} defaultSignIn={defaultSignIn} allowMultipleDailyShifts={allowMultipleDailyShifts} onAttendance={() => navigate('Attendance')} onMarkAttendance={markMemberAttendance} onSuccess={(count) => showAttendanceNotice(`${count} worker${count === 1 ? '' : 's'} signed in successfully`)} /></div></main></div>
  if (activeNav === 'Deductions') return <div className="app-shell"><WorkspaceSidebar businessName={businessName} activeNav={activeNav} onNavigate={navigate} onLogout={logout} /><main className="main-content"><header className="topbar"><div className="breadcrumbs"><span>{businessName}</span><b>/</b><strong>Deductions</strong></div></header><div className="page-content"><DeductionsPage members={members} deductions={deductions} onAdd={addDeduction} onDelete={deleteDeduction} /></div></main></div>
  if (activeNav === 'Overview') return <div className="app-shell"><WorkspaceSidebar businessName={businessName} activeNav={activeNav} onNavigate={navigate} onLogout={logout} /><main className="main-content"><header className="topbar"><div className="breadcrumbs"><span>{businessName}</span><b>/</b><strong>Overview</strong></div></header><div className="page-content"><LiveWorkspaceOverview businessName={businessName} memberName={dashboardName} memberRole={sessionMemberId === -1 ? 'Owner' : members.find((member) => member.id === sessionMemberId)?.role || role} members={members} attendance={todayAttendance} entries={attendance} sales={sales} inventory={inventory} onAttendance={() => navigate('Attendance')} /></div></main></div>

  return <div className="app-shell">
    <aside className="sidebar"><a className="brand" href={pagePaths.Overview} onClick={(event) => { event.preventDefault(); navigate('Overview') }}><span className="brand-mark">b</span><span>biz track</span></a><div className="workspace-switcher"><span className="workspace-dot">{businessName.charAt(0).toUpperCase()}</span><span><strong>{businessName}</strong><small>Business workspace</small></span><span className="chevron">⌄</span></div><nav aria-label="Main navigation"><p className="nav-label">WORKSPACE</p>{navItems.map((item) => <a key={item.label} href={pagePaths[item.label]} className={`nav-item ${activeNav === item.label ? 'active' : ''}`} onClick={(event) => { event.preventDefault(); navigate(item.label) }}><span className="nav-icon">{item.icon}</span>{item.label}{item.label === 'Inventory' && <span className="nav-badge">3</span>}</a>)}<p className="nav-label nav-label-spaced">PEOPLE</p><a href={pagePaths.Team} className={`nav-item ${activeNav === 'Team' ? 'active' : ''}`} onClick={(event) => { event.preventDefault(); navigate('Team') }}><span className="nav-icon">◎</span>Team</a><a href={pagePaths['Add member']} className={`nav-item ${activeNav === 'Add member' ? 'active' : ''}`} onClick={(event) => { event.preventDefault(); navigate('Add member') }}><span className="nav-icon">＋</span>Add member</a><a href={pagePaths.Permissions} className={`nav-item ${activeNav === 'Permissions' ? 'active' : ''}`} onClick={(event) => { event.preventDefault(); navigate('Permissions') }}><span className="nav-icon">⌘</span>Permissions</a><a href={pagePaths.ROLL} className={`nav-item ${activeNav === 'ROLL' ? 'active' : ''}`} onClick={(event) => { event.preventDefault(); navigate('ROLL') }}><span className="nav-icon">◷</span>ROLL</a><a href={pagePaths.Settings} className={`nav-item ${activeNav === 'Settings' ? 'active' : ''}`} onClick={(event) => { event.preventDefault(); navigate('Settings') }}><span className="nav-icon">⚙</span>Settings</a></nav><div className="sidebar-footer"><div className="help-mark">?</div><span>Help center</span><button className="sidebar-signout" onClick={logout}><span>↪</span>Sign out</button><button className="collapse-button">‹</button></div></aside>
    <main className="main-content"><header className="topbar"><div className="breadcrumbs"><span>Workspace</span><b>/</b><strong>{activeNav}</strong></div><div className="top-actions"><div className={`sync-status ${isOnline ? 'online' : 'offline'}`}><span className="status-dot"></span>{syncLabel}</div><button className="icon-button" aria-label="Notifications">♧<span className="notification-dot"></span></button><div className="profile-menu"><div className="avatar avatar-olive">KA</div><span><strong>Kemi A.</strong><small>{role}</small></span><span className="chevron">⌄</span></div></div></header><div className="page-content">{activeNav === 'ROLL' ? <RollPage onOpenSignIn={() => navigate('Worker sign-in')} onOpenSignOut={() => navigate('Worker checkout')} /> : activeNav === 'Attendance' ? <AttendancePage members={members} entries={todayAttendance} setMembers={setMembers} onChange={markChanged} /> : activeNav === 'Departments' ? <DepartmentsPage departments={departmentList} members={members} onAdd={() => navigate('Add department')} onDelete={deleteDepartment} /> : activeNav === 'Add department' ? <AddDepartmentPage onSubmit={addDepartment} onCancel={() => navigate('Departments')} /> : activeNav === 'Add member' ? <AddMemberPage departments={departmentList} defaultSignIn={defaultSignIn} defaultSignOut={defaultSignOut} onSubmit={addMember} onCancel={() => navigate('Team')} /> : activeNav === 'Team' ? <TeamPage members={members} onAdd={() => navigate('Add member')} onDelete={deleteMember} /> : activeNav === 'Payroll' ? <PayrollPage members={members} attendance={attendance} /> : activeNav === 'Sales' ? <SalesPage sales={sales} salesHistory={salesHistory} onAdd={addSale} onReset={resetSales} /> : activeNav === 'Inventory' ? <InventoryPage inventory={inventory} categories={storeCategories} onAdd={addInventoryItem} onAdjust={updateInventoryQuantity} /> : activeNav === 'Worker checkout' ? <WorkerSignOutPage members={members} entries={attendance} onMarkSignOut={markMemberSignOut} /> : activeNav === 'Settings' ? <SettingsPage members={members} defaultSignIn={defaultSignIn} defaultSignOut={defaultSignOut} strictSignIn={strictSignIn} setStrictSignIn={setStrictSignIn} categories={storeCategories} setCategories={setStoreCategories} setDefaultSignIn={setDefaultSignIn} setDefaultSignOut={setDefaultSignOut} setMembers={setMembers} onChange={markChanged} /> : activeNav === 'Worker sign-in' ? <LegacyWorkerSignInPage members={members} entries={attendance} strictSignIn={strictSignIn} defaultSignIn={defaultSignIn} onAttendance={toggleCurrentAttendance} onMarkAttendance={markMemberAttendance} onMarkSignOut={markMemberSignOut} /> : <LegacyOverviewPage role={role} setRole={setRole} members={members} isCheckedIn={isCheckedIn} setIsCheckedIn={toggleCurrentAttendance} isOnline={isOnline} onAttendance={() => navigate('Attendance')} />}</div></main>
  </div>
}

  function LiveOverviewPage({ memberName, members, isCheckedIn, setIsCheckedIn, isOnline, onAttendance }: { memberName: string; members: Member[]; isCheckedIn: boolean; setIsCheckedIn: () => void; isOnline: boolean; onAttendance: () => void }) { const [now, setNow] = useState(new Date()); useEffect(() => { const timer = window.setInterval(() => setNow(new Date()), 60000); return () => window.clearInterval(timer) }, []); const dateLabel = now.toLocaleDateString(undefined, { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' }); const timeLabel = now.toLocaleTimeString(undefined, { hour: '2-digit', minute: '2-digit' }); return <LegacyOverviewPage role="Owner" setRole={() => undefined} members={members} isCheckedIn={isCheckedIn} setIsCheckedIn={setIsCheckedIn} isOnline={isOnline} onAttendance={onAttendance} liveMemberName={memberName} liveDate={dateLabel} liveTime={timeLabel} /> }
  function PageHeading({ eyebrow, title, subtitle, action }: { eyebrow: string; title: string; subtitle: string; action?: React.ReactNode }) { return <div className="page-heading"><div><p className="eyebrow">{eyebrow}</p><h1>{title}</h1><p className="subheading">{subtitle}</p></div>{action && <div className="heading-actions">{action}</div>}</div> }
function PanelHeading({ title, subtitle, action }: { title: string; subtitle: string; action?: React.ReactNode }) { return <div className="panel-heading"><div><h2>{title}</h2><p>{subtitle}</p></div>{action}</div> }
function Metric({ title, value, detail, accent }: { title: string; value: string; detail: string; accent: string }) { const displayValue = value.replaceAll('₦', 'KES '); return <article className={`metric-card accent-${accent}`}><div className="metric-top"><span>{title}</span><span className="metric-icon">↗</span></div><strong>{displayValue}</strong><div className="metric-foot"><span className={detail.includes('Needs') ? 'negative' : 'positive'}>{detail}</span></div><div className="progress-track"><span style={{ width: detail.includes('Needs') ? '35%' : '72%' }}></span></div></article> }

function LegacyOverviewPage({ role, setRole, members, isCheckedIn, setIsCheckedIn, isOnline, onAttendance }: { role: Role; setRole: (role: Role) => void; members: Member[]; isCheckedIn: boolean; setIsCheckedIn: () => void; isOnline: boolean; onAttendance: () => void }) { return <><PageHeading eyebrow="MONDAY, 24 JUNE 2024" title="Good morning, Kemi ✦" subtitle="Here’s what’s happening across Biz Track today." action={<><label className="role-select"><span>Viewing as</span><select value={role} onChange={(event) => setRole(event.target.value as Role)}>{roles.map((item) => <option key={item}>{item}</option>)}</select></label><button className="primary-button" onClick={onAttendance}>View attendance <span>→</span></button></>} /><section className="metric-grid"><Metric title="Today’s sales" value="₦284,500" detail="↑ 12.8% vs. yesterday" accent="coral" /><Metric title="Team attendance" value="18 / 21" detail="85.7% present today" accent="teal" /><Metric title="Payroll this month" value="₦1.84m" detail="62% of monthly budget" accent="yellow" /><Metric title="Stock alerts" value="03" detail="Needs attention" accent="lilac" /></section><section className="dashboard-grid"><article className="panel attendance-panel"><PanelHeading title="Attendance today" subtitle="Live view of your team’s day" action={<button className="text-button" onClick={onAttendance}>View all <span>→</span></button>} /><div className="attendance-summary"><div><strong>18</strong><span>Present</span></div><div><strong>02</strong><span>Late</span></div><div><strong>01</strong><span>Off today</span></div><div className="attendance-ring"><div><strong>86%</strong><span>of team</span></div></div></div><div className="table-wrap"><table><thead><tr><th>TEAM MEMBER</th><th>DEPARTMENT</th><th>STATUS</th><th>CHECK-IN</th></tr></thead><tbody>{members.slice(0, 4).map((member, index) => <tr key={member.id}><td><div className="person-cell"><span className={`avatar avatar-${member.color}`}>{member.initials}</span><strong>{member.name}</strong></div></td><td>{member.department}</td><td><span className={`status-pill ${index === 2 ? 'late' : 'present'}`}><i></i>{index === 2 ? 'Late' : 'Present'}</span></td><td>{index === 2 ? '09:17 AM' : '08:52 AM'}</td></tr>)}</tbody></table></div></article><article className="panel checkin-panel"><PanelHeading title="Your attendance" subtitle="Keep your day on track" action={<span className="today-tag">TODAY</span>} /><div className="checkin-state"><span className="checkin-icon">{isCheckedIn ? '✓' : '○'}</span><div><strong>{isCheckedIn ? 'You are checked in' : 'You are checked out'}</strong><span>{isCheckedIn ? 'Started at 08:46 AM' : 'Tap below to start your day'}</span></div></div><button className="attendance-button" onClick={setIsCheckedIn}>{isCheckedIn ? 'Check out' : 'Check in'} <span>→</span></button><div className="checkin-note">◷ Automatic sync is {isOnline ? 'on' : 'paused offline'}</div></article></section><section className="lower-grid"><article className="panel insight-panel"><PanelHeading title="Sales performance" subtitle="Revenue across the last 7 days" /><div className="fake-chart"><span>₦300k</span><div className="chart-bars"><i></i><i></i><i></i><i></i><i></i><i></i><i></i></div><span>₦0</span></div></article><article className="panel insight-panel"><PanelHeading title="Inventory watchlist" subtitle="Items that need your attention" action={<button className="text-button">Manage <span>→</span></button>} /><div className="inventory-list"><div className="inventory-item"><span className="product-icon product-red">☕</span><div><strong>Arabica coffee beans</strong><small>Warehouse · 2kg left</small></div><span className="stock-status critical">Critical</span></div><div className="inventory-item"><span className="product-icon product-green">◒</span><div><strong>Fresh milk</strong><small>Cold storage · 8L left</small></div><span className="stock-status low">Low stock</span></div></div></article></section></> }

function AttendancePage({ members, entries, setMembers, onChange }: { members: Member[]; entries: AttendanceEntry[]; setMembers?: React.Dispatch<React.SetStateAction<Member[]>>; onChange?: () => void }) { const counts = { Present: entries.filter((entry) => entry.status === 'Present').length, Late: entries.filter((entry) => entry.status === 'Late').length, Absent: entries.filter((entry) => entry.status === 'Absent').length, Off: entries.filter((entry) => entry.status === 'Off').length }; return <><PageHeading eyebrow="TEAM MANAGEMENT / ATTENDANCE" title="Attendance" subtitle="See how your employees have been showing up each day." action={<button className="filter-button">Today · 24 Jun 2024 <span>⌄</span></button>} /><section className="metric-grid attendance-metrics"><Metric title="Present today" value={String(counts.Present)} detail="Checked in on time" accent="teal" /><Metric title="Late arrivals" value={String(counts.Late).padStart(2, '0')} detail="Needs follow-up" accent="yellow" /><Metric title="Absent" value={String(counts.Absent).padStart(2, '0')} detail="No sign-in recorded" accent="coral" /><Metric title="Team coverage" value="86%" detail="18 of 21 scheduled" accent="lilac" /></section><article className="panel attendance-review"><PanelHeading title="Employee attendance" subtitle="Daily sign-in and sign-out records for your team" action={<button className="filter-button">All departments <span>⌄</span></button>} /><div className="table-wrap"><table><thead><tr><th>EMPLOYEE</th><th>DEPARTMENT</th><th>ROLE</th><th>STATUS</th><th>CHECK-IN</th><th>CHECK-OUT</th></tr></thead><tbody>{entries.map((entry) => { const member = members.find((item) => item.id === entry.memberId); if (!member) return null; return <tr key={member.id}><td><div className="person-cell"><span className={`avatar avatar-${member.color}`}>{member.initials}</span><strong>{member.name}</strong></div></td><td>{member.department}</td><td>{member.role}</td><td><span className={`status-pill ${entry.status.toLowerCase()}`}><i></i>{entry.status}</span></td><td>{entry.checkIn}</td><td>{entry.checkOut}</td></tr> })}</tbody></table></div></article><p className="page-footer"><span><i className="footer-dot"></i> Attendance is saved locally and will sync automatically</span><span>Showing {members.length} team members</span></p></> }

function TeamPage({ members, onAdd, onDelete }: { members: Member[]; onAdd: () => void; onDelete: (id: number) => void }) { const [selectedDepartment, setSelectedDepartment] = useState('All departments'); const departmentOptions = ['All departments', ...Array.from(new Set(members.map((member) => member.department)))]; const visibleMembers = selectedDepartment === 'All departments' ? members : members.filter((member) => member.department === selectedDepartment); return <><PageHeading eyebrow="PEOPLE / TEAM" title="Your team" subtitle="Manage members and keep everyone connected to the right department." action={<button className="primary-button" onClick={onAdd}><span>＋</span> Add member</button>} /><article className="panel team-panel"><PanelHeading title={`${visibleMembers.length} team members`} subtitle="Contact details and current assignments" action={<select className="filter-button" value={selectedDepartment} onChange={(event) => setSelectedDepartment(event.target.value)}>{departmentOptions.map((department) => <option key={department}>{department}</option>)}</select>} /><div className="table-wrap"><table><thead><tr><th>WORKER ID</th><th>TEAM MEMBER</th><th>PHONE</th><th>EMAIL</th><th>DEPARTMENT</th><th>ROLE</th><th>ACTION</th></tr></thead><tbody>{visibleMembers.map((member) => <tr key={member.id}><td><strong>#{member.id}</strong></td><td><div className="person-cell"><span className={`avatar avatar-${member.color}`}>{member.initials}</span><strong>{member.name}</strong></div></td><td>{member.phone}</td><td>{member.email}</td><td>{member.department}</td><td><span className="role-pill">{member.role}</span></td><td><button className="delete-button" aria-label={`Delete ${member.name}`} onClick={() => onDelete(member.id)}>×</button></td></tr>)}</tbody></table></div></article></> }

function PayrollPage({ members, attendance, onUpdateStatus }: { members: Member[]; attendance: AttendanceEntry[]; onUpdateStatus?: (memberIds: number[], startDate: string, endDate: string, status: PaymentStatus) => void }) {
  const [period, setPeriod] = useState('month')
  const [selectedDay, setSelectedDay] = useState(today)
  const [customStart, setCustomStart] = useState(today)
  const [customEnd, setCustomEnd] = useState(today)
  const [statusFilter, setStatusFilter] = useState('All statuses')
  const [departmentFilter, setDepartmentFilter] = useState('All departments')
  const [selectedMembers, setSelectedMembers] = useState<number[]>([])
  const range = period === 'today' ? { start: today, end: today } : period === 'day' ? { start: selectedDay, end: selectedDay } : period === 'week' ? { start: '2024-06-24', end: '2024-06-30' } : period === 'custom' ? { start: customStart, end: customEnd } : { start: '2024-06-01', end: '2024-06-30' }
  const completedEntries = attendance.filter((entry) => entry.checkOut !== '—' && entry.date >= range.start && entry.date <= range.end)
  const rows = members.map((member) => {
    const entries = completedEntries.filter((entry) => entry.memberId === member.id)
    const unpaidEntries = entries.filter((entry) => entry.paymentStatus !== 'Paid')
    const statuses = entries.length === 0 ? ['No shifts'] : Array.from(new Set(entries.map((entry) => entry.paymentStatus || 'Pending')))
    const status = statuses.length === 1 ? statuses[0] : 'Mixed'
    return { member, entries, unpaidEntries, shifts: unpaidEntries.length, owed: unpaidEntries.length * member.payRate, status }
  }).filter((row) => departmentFilter === 'All departments' || row.member.department === departmentFilter).filter((row) => statusFilter === 'All statuses' || row.status === statusFilter)
  const departments = ['All departments', ...Array.from(new Set(members.map((member) => member.department)))]
  const totalOwed = rows.reduce((sum, row) => sum + row.owed, 0)
  const visibleIds = rows.map((row) => row.member.id)
  useEffect(() => {
    document.querySelectorAll('.payroll-toolbar + .table-wrap input[type="checkbox"]').forEach((checkbox) => checkbox.removeAttribute('disabled'))
  }, [rows, selectedMembers])
  const toggleMember = (memberId: number) => setSelectedMembers((current) => current.includes(memberId) ? current.filter((id) => id !== memberId) : [...current, memberId])
  const toggleVisible = () => setSelectedMembers((current) => visibleIds.every((id) => current.includes(id)) ? current.filter((id) => !visibleIds.includes(id)) : Array.from(new Set([...current, ...visibleIds])))
  const updateSelected = (status: PaymentStatus) => { const ids = selectedMembers.filter((id) => visibleIds.includes(id)); if (!ids.length) return; (onUpdateStatus || (window as any).__biztrackUpdatePayrollStatus)?.(ids, range.start, range.end, status); setSelectedMembers([]) }
  const statusClass = (status: string) => status.toLowerCase().replace(' ', '-')
  return <><PageHeading eyebrow="WORKSPACE / PAYROLL" title="Payroll" subtitle="Filter completed shifts, review what each employee is owed, and record payment status." action={<button className="primary-button" onClick={() => updateSelected('Paid')} disabled={!selectedMembers.length}><span>＋</span> Mark selected paid</button>} /><section className="metric-grid"><Metric title="Amount owed" value={`₦${totalOwed.toLocaleString()}`} detail={`${rows.filter((row) => row.owed > 0).length} employees with unpaid shifts`} accent="yellow" /><Metric title="Filtered shifts" value={String(rows.reduce((sum, row) => sum + row.shifts, 0))} detail="Completed and not paid" accent="teal" /><Metric title="Paid in view" value={`₦${rows.reduce((sum, row) => sum + (row.entries.length - row.shifts) * row.member.payRate, 0).toLocaleString()}`} detail="Already settled" accent="coral" /><Metric title="Team in view" value={String(rows.length)} detail="Matching employees" accent="lilac" /></section><article className="panel team-panel"><PanelHeading title="Employee pay schedule" subtitle={`Showing ${range.start} to ${range.end}. A new completed shift starts earning again.`} action={<div className="payroll-filters"><select aria-label="Payroll period" className="filter-button" value={period} onChange={(event) => setPeriod(event.target.value)}><option value="month">This month</option><option value="week">This week</option><option value="today">Today</option><option value="day">Particular day</option><option value="custom">Custom range</option></select>{period === 'day' && <input aria-label="Particular day" type="date" value={selectedDay} onChange={(event) => setSelectedDay(event.target.value)} />}{period === 'custom' && <><input aria-label="Start date" type="date" value={customStart} onChange={(event) => setCustomStart(event.target.value)} /><input aria-label="End date" type="date" value={customEnd} onChange={(event) => setCustomEnd(event.target.value)} /></>}</div>} /><div className="payroll-toolbar"><label><span>Department</span><select value={departmentFilter} onChange={(event) => setDepartmentFilter(event.target.value)}>{departments.map((department) => <option key={department}>{department}</option>)}</select></label><label><span>Payment status</span><select value={statusFilter} onChange={(event) => setStatusFilter(event.target.value)}><option>All statuses</option><option>Pending</option><option>Paid</option><option>On hold</option><option>Mixed</option><option>No shifts</option></select></label><div className="payroll-bulk-actions"><button className="secondary-button" onClick={() => updateSelected('Pending')} disabled={!selectedMembers.length}>Mark pending</button><button className="secondary-button" onClick={() => updateSelected('On hold')} disabled={!selectedMembers.length}>Put on hold</button></div></div><div className="table-wrap"><table><thead><tr><th><input aria-label="Select visible employees" type="checkbox" checked={visibleIds.length > 0 && visibleIds.every((id) => selectedMembers.includes(id))} onChange={toggleVisible} /></th><th>EMPLOYEE</th><th>FREQUENCY</th><th>PAY RATE</th><th>UNPAID SHIFTS</th><th>AMOUNT OWED</th><th>STATUS</th></tr></thead><tbody>{rows.map((row) => <tr key={row.member.id}><td><input aria-label={`Select ${row.member.name}`} type="checkbox" checked={selectedMembers.includes(row.member.id)} onChange={() => toggleMember(row.member.id)} disabled={!row.entries.length} /></td><td><div className="person-cell"><span className={`avatar avatar-${row.member.color}`}>{row.member.initials}</span><strong>{row.member.name}</strong></div></td><td>{row.member.payFrequency}</td><td>₦{row.member.payRate.toLocaleString()} / {row.member.payFrequency === 'Daily' ? 'day' : row.member.payFrequency === 'Weekly' ? 'week' : 'month'}</td><td>{row.shifts}</td><td><strong>₦{row.owed.toLocaleString()}</strong></td><td><span className={`status-pill ${statusClass(row.status)}`}><i></i>{row.status}</span></td></tr>)}</tbody></table></div></article></>
}


function DeductionsPage({ members, deductions, onAdd, onDelete }: { members: Member[]; deductions: Deduction[]; onAdd: (deduction: Deduction) => void; onDelete: (id: number) => void }) {
  const [selectedMemberId, setSelectedMemberId] = useState(members[0]?.id || '')
  const total = deductions.reduce((sum, deduction) => sum + deduction.amount, 0)
  const submit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault()
    const form = new FormData(event.currentTarget)
    const memberId = Number(form.get('memberId'))
    const amount = Number(form.get('amount'))
    const reason = String(form.get('reason') || '').trim()
    if (!memberId || amount <= 0 || !reason) return
    onAdd({ id: Date.now(), memberId, amount, reason, date: String(form.get('date') || today) })
    event.currentTarget.reset()
    setSelectedMemberId(members[0]?.id || '')
  }
  return <><PageHeading eyebrow="PEOPLE / PAYROLL" title="Deductions" subtitle="Record approved deductions when an employee needs an amount taken from their pay." action={<span className="deduction-note">Changes save to this workspace</span>} /><section className="metric-grid"><Metric title="Total deducted" value={`₦${total.toLocaleString()}`} detail={`${deductions.length} recorded deduction${deductions.length === 1 ? '' : 's'}`} accent="coral" /><Metric title="This month" value={`₦${deductions.filter((deduction) => deduction.date.slice(0, 7) === today.slice(0, 7)).reduce((sum, deduction) => sum + deduction.amount, 0).toLocaleString()}`} detail="Current payroll period" accent="yellow" /><Metric title="Employees affected" value={String(new Set(deductions.map((deduction) => deduction.memberId)).size)} detail="With deductions on file" accent="teal" /><Metric title="Average deduction" value={`₦${deductions.length ? Math.round(total / deductions.length).toLocaleString() : '0'}`} detail="Across all records" accent="lilac" /></section><div className="deductions-layout"><form className="panel member-form sales-form" onSubmit={submit}><PanelHeading title="Add a deduction" subtitle="Only record deductions that have been reviewed and approved." /><div className="form-grid single-field"><label><span>Employee <b>*</b></span><select name="memberId" value={selectedMemberId} onChange={(event) => setSelectedMemberId(Number(event.target.value))} required>{members.map((member) => <option key={member.id} value={member.id}>{member.name} · {member.department}</option>)}</select></label><label><span>Amount <b>*</b></span><input name="amount" type="number" min="1" step="0.01" placeholder="e.g. 5000" required /></label><label><span>Reason <b>*</b></span><input name="reason" placeholder="e.g. Stock shortage" required /></label><label><span>Effective date <b>*</b></span><input name="date" type="date" defaultValue={today} required /></label></div><div className="form-actions"><button type="submit" className="primary-button"><span>＋</span> Record deduction</button></div></form><article className="panel team-panel"><PanelHeading title="Deduction history" subtitle="Review amounts recorded against employee pay." />{deductions.length ? <div className="table-wrap"><table><thead><tr><th>EMPLOYEE</th><th>REASON</th><th>DATE</th><th>AMOUNT</th><th>ACTION</th></tr></thead><tbody>{deductions.map((deduction) => { const member = members.find((item) => item.id === deduction.memberId); return <tr key={deduction.id}><td><div className="person-cell"><span className={`avatar avatar-${member?.color || 'mint'}`}>{member?.initials || '?'}</span><strong>{member?.name || 'Removed employee'}</strong></div></td><td>{deduction.reason}</td><td>{deduction.date}</td><td><strong>₦{deduction.amount.toLocaleString()}</strong></td><td><button className="delete-button" aria-label={`Remove deduction for ${member?.name || 'employee'}`} onClick={() => onDelete(deduction.id)}>×</button></td></tr>})}</tbody></table></div> : <div className="deductions-empty"><strong>No deductions recorded</strong><p>Approved deductions will appear here for review.</p></div>}</article></div></>
}
function SalesPage({ sales, salesHistory, onAdd, onReset }: { sales: Sale[]; salesHistory: Sale[]; onAdd: (sale: Sale) => void; onReset: () => void }) { const total = sales.reduce((sum, sale) => sum + sale.amount, 0); const cashTotal = sales.filter((sale) => sale.paymentMethod === 'Cash').reduce((sum, sale) => sum + sale.amount, 0); const creditTotal = sales.filter((sale) => sale.paymentMethod === 'Credit').reduce((sum, sale) => sum + sale.amount, 0); const mobileTotal = sales.filter((sale) => sale.paymentMethod === 'Mobile money').reduce((sum, sale) => sum + sale.amount, 0); const submit = (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const form = new FormData(event.currentTarget); onAdd({ id: Date.now(), amount: Number(form.get('amount')), paymentMethod: String(form.get('paymentMethod')) as PaymentMethod, date: today, time: '', cashier: '' }); event.currentTarget.reset() }; const allHistory = [...sales, ...salesHistory]; return <><PageHeading eyebrow="WORKSPACE / SALES" title="Sales" subtitle="Record the total sales received today and track how customers paid." action={<button className="secondary-button" onClick={onReset}>Archive today</button>} /><section className="metric-grid"><Metric title="Today’s sales" value={`KES ${total.toLocaleString()}`} detail={`${sales.length} record${sales.length === 1 ? '' : 's'} today`} accent="coral" /><Metric title="Cash" value={`KES ${cashTotal.toLocaleString()}`} detail="Received in cash" accent="yellow" /><Metric title="Credit" value={`KES ${creditTotal.toLocaleString()}`} detail="Recorded on credit" accent="teal" /><Metric title="Mobile money" value={`KES ${mobileTotal.toLocaleString()}`} detail="Received by mobile money" accent="lilac" /></section><div className="sales-layout"><form className="panel member-form sales-form" onSubmit={submit}><PanelHeading title="Record daily sales" subtitle="Choose where the money was received." /><div className="form-grid single-field"><label><span>Total amount <b>*</b></span><input name="amount" type="number" min="0.01" step="0.01" required placeholder="e.g. 12500" /></label><label><span>Money received through <b>*</b></span><select name="paymentMethod" defaultValue="Cash" required><option>Cash</option><option>Credit</option><option>Mobile money</option></select></label></div><button className="primary-button" type="submit"><span>＋</span> Record sales</button></form><article className="panel team-panel"><PanelHeading title="Sales history" subtitle="Every record includes the registered cashier name and exact recording time." /><div className="table-wrap"><table><thead><tr><th>AMOUNT</th><th>PAYMENT METHOD</th><th>DATE</th><th>TIME</th><th>RECORDED BY</th></tr></thead><tbody>{allHistory.length ? allHistory.map((sale) => <tr key={`${sale.id}-${sale.time}`}><td><strong>KES {sale.amount.toLocaleString()}</strong></td><td><span className="role-pill">{sale.paymentMethod || 'Cash'}</span></td><td>{sale.date}</td><td>{sale.time || 'Time unavailable'}</td><td>{sale.cashier || 'Registered account'}</td></tr>) : <tr><td colSpan={5}>No sales recorded yet.</td></tr>}</tbody></table></div></article></div></> }

function InventoryPage({ inventory, categories, onAdd, onAdjust }: { inventory: InventoryItem[]; categories: string[]; onAdd: (item: InventoryItem) => void; onAdjust: (id: number, amount: number) => void }) { const [category, setCategory] = useState('All'); const visibleItems = category === 'All' ? inventory : inventory.filter((item) => item.category === category); const submit = (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const form = new FormData(event.currentTarget); onAdd({ id: Date.now(), name: String(form.get('name')), category: String(form.get('category')), quantity: Number(form.get('quantity')), unit: String(form.get('unit')), reorderAt: Number(form.get('reorderAt')) }); event.currentTarget.reset() }; return <><PageHeading eyebrow="WORKSPACE / STORE" title="Store inventory" subtitle="See what is in the store, grouped by category, and keep stock levels healthy." /><section className="metric-grid"><Metric title="Items tracked" value={String(inventory.length)} detail="Across all categories" accent="teal" /><Metric title="Low stock" value={String(inventory.filter((item) => item.quantity <= item.reorderAt).length).padStart(2, '0')} detail="Needs restocking" accent="coral" /><Metric title="Categories" value={String(categories.length - 1)} detail="Organized stock" accent="yellow" /><Metric title="Units in store" value={String(inventory.reduce((sum, item) => sum + item.quantity, 0))} detail="Total quantity" accent="lilac" /></section><div className="sales-layout"><form className="panel member-form sales-form" onSubmit={submit}><PanelHeading title="Add stock item" subtitle="Add products, supplies, or ingredients" /><div className="form-grid single-field"><label><span>Item name <b>*</b></span><input name="name" placeholder="e.g. Sugar" required /></label><label><span>Category <b>*</b></span><select name="category"><option>Beverages</option><option>Food</option><option>Dairy</option><option>Supplies</option><option>Retail</option></select></label><label><span>Quantity <b>*</b></span><input name="quantity" type="number" min="0" required placeholder="20" /></label><label><span>Unit <b>*</b></span><input name="unit" placeholder="kg, L, pieces" required /></label><label><span>Reorder at</span><input name="reorderAt" type="number" min="0" defaultValue="5" /></label></div><button className="primary-button" type="submit"><span>＋</span> Add to store</button></form><article className="panel team-panel"><PanelHeading title="Stock by category" subtitle="Adjust quantities when stock arrives or is used" action={<select className="filter-button" value={category} onChange={(event) => setCategory(event.target.value)}>{categories.map((item) => <option key={item}>{item}</option>)}</select>} /><div className="table-wrap"><table><thead><tr><th>ITEM</th><th>CATEGORY</th><th>IN STORE</th><th>STATUS</th><th>ADJUST</th></tr></thead><tbody>{visibleItems.map((item) => <tr key={item.id}><td><strong>{item.name}</strong></td><td><span className="role-pill">{item.category}</span></td><td>{item.quantity} {item.unit}</td><td><span className={`status-pill ${item.quantity <= item.reorderAt ? 'late' : 'present'}`}><i></i>{item.quantity <= item.reorderAt ? 'Low stock' : 'In stock'}</span></td><td><button className="quantity-button" onClick={() => onAdjust(item.id, -1)}>-</button><button className="quantity-button" onClick={() => onAdjust(item.id, 1)}>+</button></td></tr>)}</tbody></table></div></article></div></> }

function DepartmentsPage({ departments, members, onAdd, onDelete }: { departments: string[]; members: Member[]; onAdd: () => void; onDelete: (name: string) => void }) { return <><PageHeading eyebrow="WORKSPACE / ORGANIZATION" title="Departments" subtitle="Organize your team and see where every employee is assigned." action={<button className="primary-button" onClick={onAdd}><span>＋</span> Add department</button>} /><article className="panel department-panel"><PanelHeading title={`${departments.length} departments`} subtitle="Available departments in this workspace" /><div className="department-grid">{departments.map((department, index) => <div className="department-card" key={department}><div className={`department-icon department-icon-${index % 4}`}>▦</div><div className="department-card-copy"><h3>{department}</h3><p>{members.filter((member) => member.department === department).length} team members</p></div><button className="delete-button" aria-label={`Delete ${department}`} onClick={() => onDelete(department)}>×</button></div>)}</div></article></> }

function AddDepartmentPage({ onSubmit, onCancel }: { onSubmit: (event: FormEvent<HTMLFormElement>) => void; onCancel: () => void }) { return <><PageHeading eyebrow="WORKSPACE / ORGANIZATION" title="Add a department" subtitle="Create a department to make team assignments easier to manage." /><form className="panel member-form" onSubmit={onSubmit}><div className="form-heading"><div><h2>Department details</h2><p>Give the department a clear name your team will recognize.</p></div><span className="required-note">* Required</span></div><div className="form-grid single-field"><label><span>Department name <b>*</b></span><input name="departmentName" placeholder="e.g. Customer service" required /></label></div><div className="form-actions"><button type="button" className="secondary-button" onClick={onCancel}>Cancel</button><button type="submit" className="primary-button"><span>＋</span> Add department</button></div></form></> }

function AddMemberPage({ departments, defaultSignIn, defaultSignOut, onSubmit, onCancel }: { departments: string[]; defaultSignIn: string; defaultSignOut: string; onSubmit: (event: FormEvent<HTMLFormElement>) => void; onCancel: () => void }) { return <><PageHeading eyebrow="PEOPLE / TEAM" title="Add a team member" subtitle="Create a profile, pay schedule, and attendance schedule." /><form className="panel member-form" onSubmit={onSubmit}><div className="form-heading"><div><h2>Member details</h2><p>Pay is added when the employee completes a sign-in and sign-out shift.</p></div><span className="required-note">* Required</span></div><div className="form-grid"><label><span>Full name <b>*</b></span><input name="fullName" placeholder="e.g. Chidi Okafor" required /></label><label><span>Phone number <b>*</b></span><input name="phone" placeholder="e.g. +234 803 123 4567" required /></label><label><span>Email address</span><input name="email" type="email" placeholder="name@business.com or NA" /></label><label><span>Department <b>*</b></span><select name="department" defaultValue={departments[0]} required>{departments.length ? departments.map((department) => <option key={department}>{department}</option>) : <option value="Unassigned">Unassigned</option>}</select></label><label><span>Pay rate <b>*</b></span><input name="payRate" type="number" min="0" step="0.01" placeholder="1000" required /></label><label><span>Pay frequency <b>*</b></span><select name="payFrequency" defaultValue="Daily"><option>Daily</option><option>Weekly</option><option>Monthly</option></select></label><label><span>Sign-in time</span><input name="signInTime" type="time" defaultValue={defaultSignIn} /></label><label><span>Sign-out time</span><input name="signOutTime" type="time" defaultValue={defaultSignOut} /></label></div><section className="account-access-section"><div><h2>Login account</h2><p>Enable this only if the employee should sign in and receive page access from the owner.</p></div><label className="account-toggle"><input name="hasAccount" type="checkbox" /><span><strong>Give this member a login account</strong><small>Only enabled account holders appear in Permissions.</small></span></label><div className="form-grid account-fields"><label><span>Username</span><input name="username" placeholder="e.g. chidi.okafor" /></label><label><span>Password</span><input name="password" type="password" minLength={6} placeholder="At least 6 characters" /></label></div></section><div className="form-actions"><button type="button" className="secondary-button" onClick={onCancel}>Cancel</button><button type="submit" className="primary-button"><span>＋</span> Add member</button></div></form></> }

function SettingsPage({ members, defaultSignIn, defaultSignOut, strictSignIn, setStrictSignIn, categories, setCategories, setDefaultSignIn, setDefaultSignOut, setMembers, onChange }: { members: Member[]; defaultSignIn: string; defaultSignOut: string; strictSignIn: boolean; setStrictSignIn: (value: boolean) => void; categories: string[]; setCategories: (value: string[]) => void; setDefaultSignIn: (value: string) => void; setDefaultSignOut: (value: string) => void; setMembers: (members: Member[]) => void; onChange: () => void }) { return <><PageHeading eyebrow="WORKSPACE / SETTINGS" title="Settings" subtitle="Set attendance rules and individual employee schedules." /><section className="settings-stack"><article className="panel member-form"><PanelHeading title="Default attendance times" subtitle="New members use these times unless you set a specific schedule." /><div className="form-grid settings-times"><label><span>Default sign-in time</span><input type="time" value={defaultSignIn} onChange={(event) => { setDefaultSignIn(event.target.value); onChange() }} /></label><label><span>Default sign-out time</span><input type="time" value={defaultSignOut} onChange={(event) => { setDefaultSignOut(event.target.value); onChange() }} /></label><label><span>Strict sign-in checks</span><input type="checkbox" checked={strictSignIn} onChange={(event) => { setStrictSignIn(event.target.checked); onChange() }} /></label><label><span>Inventory categories</span><input type="text" value={categories.join(', ')} onChange={(event) => { const nextCategories = event.target.value.split(',').map((item) => item.trim()).filter(Boolean); setCategories(nextCategories.length ? nextCategories : categories); onChange() }} /></label></div></article><article className="panel team-panel"><PanelHeading title="Employee attendance settings" subtitle="Set the expected sign-in and sign-out time for specific people" /><div className="table-wrap"><table><thead><tr><th>EMPLOYEE</th><th>EXPECTED SIGN-IN</th><th>EXPECTED SIGN-OUT</th><th>ACTION</th></tr></thead><tbody>{members.map((member) => <tr key={member.id}><td><div className="person-cell"><span className={`avatar avatar-${member.color}`}>{member.initials}</span><strong>{member.name}</strong></div></td><td><input className="table-input" type="time" value={member.signInTime} onChange={(event) => { setMembers(members.map((item) => item.id === member.id ? { ...item, signInTime: event.target.value } : item)); onChange() }} /></td><td><input className="table-input" type="time" value={member.signOutTime} onChange={(event) => { setMembers(members.map((item) => item.id === member.id ? { ...item, signOutTime: event.target.value } : item)); onChange() }} /></td><td><span className="status-pill present"><i></i>Saved locally</span></td></tr>)}</tbody></table></div></article></section></> }

function LegacyWorkerSignInPage({ members, entries, strictSignIn, defaultSignIn, onAttendance, onMarkAttendance, onMarkSignOut }: { members: Member[]; entries: AttendanceEntry[]; strictSignIn: boolean; defaultSignIn: string; onAttendance: () => void; onMarkAttendance: (memberId: number, status: 'Present' | 'Absent') => void; onMarkSignOut?: (memberId: number) => boolean }) { const [selectedDepartment, setSelectedDepartment] = useState(''); const [selectedWorkerId, setSelectedWorkerId] = useState<number | ''>(''); const departments = Array.from(new Set(members.map((member) => member.department))); const visibleMembers = selectedDepartment ? members.filter((member) => member.department === selectedDepartment) : []; const selectedMember = visibleMembers.find((member) => member.id === selectedWorkerId) ?? null; const selectedEntry = selectedMember ? entries.find((entry) => entry.memberId === selectedMember.id && entry.date === today) : undefined; const isLockedAbsent = selectedEntry?.status === 'Off'; const [selectedStatus, setSelectedStatus] = useState<'Present' | 'Absent'>('Present');

  useEffect(() => {
    if (!selectedMember) {
      setSelectedStatus('Present')
      return
    }
    setSelectedStatus(selectedEntry?.status === 'Off' ? 'Absent' : selectedEntry?.status === 'Absent' ? 'Absent' : 'Present')
  }, [selectedMember, selectedEntry])

  if (new URLSearchParams(window.location.search).get('mode') === 'bulk') return <BulkAttendancePage action="Sign in" members={members} entries={entries} onMarkAttendance={onMarkAttendance} onMarkSignOut={() => false} onSuccess={(count) => (window as any).__attendanceSuccess?.(`${count} worker${count === 1 ? '' : 's'} signed in successfully`)} />

  const handleStatusChange = (status: 'Present' | 'Absent') => {
    if (!selectedMember || isLockedAbsent) return
    setSelectedStatus(status)
    onMarkAttendance(selectedMember.id, status)
    if (status === 'Present') (window as any).__attendanceSuccess?.('1 worker signed in successfully')
  }

  return <><PageHeading eyebrow="PEOPLE / SIGN-IN" title="Worker sign-in" subtitle={strictSignIn ? 'Strict sign-in checks are enabled for hourly staff.' : 'Flexible sign-in mode is active for this workspace.'} action={<button className="primary-button" onClick={onAttendance}><span>→</span> View attendance</button>} /><article className="panel member-form"><PanelHeading title="Today’s check-in" subtitle="Use the default time or update it from settings." /><div style={{ display: 'flex', gap: '1rem', flexWrap: 'wrap' }}><label style={{ flex: 1, minWidth: '220px' }}><span>Department filter</span><select value={selectedDepartment} onChange={(event) => { setSelectedDepartment(event.target.value); setSelectedWorkerId('') }}><option value="">Select department</option>{departments.map((department) => <option key={department} value={department}>{department}</option>)}</select></label><label style={{ flex: 1, minWidth: '220px' }}><span>Worker ID</span><select value={selectedWorkerId} onChange={(event) => setSelectedWorkerId(Number(event.target.value) || '')} disabled={!selectedDepartment}><option value="">{selectedDepartment ? 'Select worker ID' : 'Choose a department first'}</option>{visibleMembers.map((member) => <option key={member.id} value={member.id}>ID {member.id}</option>)}</select></label></div>{selectedMember && <><div style={{ marginTop: '1rem' }}><label><span>Registered worker</span><input value={selectedMember.name} readOnly /></label></div><div style={{ marginTop: '1rem' }}><label><span>Default sign-in time</span><input value={defaultSignIn} readOnly /></label></div><div style={{ marginTop: '1rem', display: 'flex', gap: '1rem', flexWrap: 'wrap' }}><button type="button" className={selectedStatus === 'Present' ? 'primary-button' : 'secondary-button'} disabled={isLockedAbsent || selectedStatus === 'Present'} onClick={() => handleStatusChange('Present')}>Present</button><button type="button" className={selectedStatus === 'Absent' ? 'primary-button' : 'secondary-button'} disabled={isLockedAbsent || selectedStatus === 'Absent'} onClick={() => handleStatusChange('Absent')}>Absent</button>{isLockedAbsent && <span style={{ alignSelf: 'center', color: '#7a5b3f', fontWeight: 600 }}>Off-day lock: absent is fixed</span>}</div>{selectedMember && <div style={{ marginTop: '1rem', display: 'grid', gap: '0.75rem' }}><div className="table-wrap"><table><thead><tr><th>WORKER ID</th><th>NAME</th><th>PHONE</th></tr></thead><tbody>{visibleMembers.map((member) => <tr key={member.id}><td>#{member.id}</td><td>{member.name}</td><td>{member.phone}</td></tr>)}</tbody></table></div></div>}</> }<div className="form-actions"><button type="button" className="primary-button" onClick={onAttendance}>Mark attendance</button></div></article></> }

function RegisterPage({ onNavigate, onComplete }: { onNavigate: (page: string) => void; onComplete: (account: OwnerAccount) => void }) {
  const [step, setStep] = useState(1)
  const [details, setDetails] = useState({ name: '', username: '', password: '', phone: '', business: '', industry: '', plan: 'Starter' })
  const [code, setCode] = useState('')
  const [generatedCode] = useState(() => `BT-${Math.floor(100000 + Math.random() * 900000)}`)
  const [error, setError] = useState('')
  const update = (event: FormEvent<HTMLInputElement | HTMLSelectElement>) => { const next = { ...details, [event.currentTarget.name]: event.currentTarget.value }; setDetails(next) }
  const next = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault(); setError('')
    if (step === 1 && (!details.name.trim() || details.username.trim().length < 3 || details.password.length < 6 || !details.phone.trim())) { setError('Enter your name, phone, a username of at least 3 characters, and a password of at least 6 characters.'); return }
    if (step === 2 && (!details.business.trim() || !details.industry)) { setError('Add your business name and choose an industry.'); return }
    if (step === 3) { setStep(4); return }
    if (step === 4) { if (code.trim().toUpperCase() !== generatedCode) { setError('That confirmation code does not match.'); return } onComplete({ name: details.name.trim(), username: details.username.trim(), password: details.password, business: details.business.trim() }); return }
    setStep(step + 1)
  }
  const stepTitles = ['Your details', 'Your business', 'Terms and package', 'Confirm purchase']
  return <div className="register-page"><header className="register-header"><button className="welcome-brand" onClick={() => onNavigate('Welcome')}><span className="welcome-mark">b</span><span>biz track</span></button><button className="register-back" onClick={() => onNavigate('Welcome')}>Back to welcome</button></header><main className="register-layout"><section className="register-intro"><p className="welcome-kicker">SET UP YOUR WORKSPACE</p><h1>A clear start for<br /><em>better work.</em></h1><p>Take four short steps to create the owner account, choose a package, and open your business workspace.</p><div className="register-assurance"><span>✓</span><div><strong>Owner-led by design</strong><small>You decide who joins and what each person can access.</small></div></div></section><section className="register-card"><div className="register-progress">{stepTitles.map((title, index) => <div key={title} className={index + 1 <= step ? 'complete' : ''}><b>0{index + 1}</b><span>{title}</span></div>)}</div><form onSubmit={next}><p className="eyebrow">STEP 0{step} OF 04</p><h2>{stepTitles[step - 1]}</h2><p className="register-help">{step === 1 ? 'This will be your owner profile and sign-in.' : step === 2 ? 'Tell us where Biz Track will help your team.' : step === 3 ? 'Review the plan and accept the terms to continue.' : 'The system created a purchase code. Enter it to finish.'}</p>{step === 1 && <div className="form-grid register-fields"><label><span>Full name *</span><input name="name" value={details.name} onChange={update} placeholder="e.g. Kemi Adebayo" /></label><label><span>Phone number *</span><input name="phone" value={details.phone} onChange={update} placeholder="e.g. +234 803 123 4567" /></label><label><span>Username *</span><input name="username" value={details.username} onChange={update} placeholder="Choose a username" /></label><label><span>Password *</span><input name="password" type="password" value={details.password} onChange={update} placeholder="At least 6 characters" /></label></div>}{step === 2 && <div className="form-grid register-fields"><label><span>Business name *</span><input name="business" value={details.business} onChange={update} placeholder="e.g. Northstar Cafe" /></label><label><span>Industry *</span><select name="industry" value={details.industry} onChange={update}><option value="">Choose an industry</option><option>Retail</option><option>Restaurant and hospitality</option><option>Professional services</option><option>Other</option></select></label></div>}{step === 3 && <div className="package-choice"><article><span>Recommended</span><h3>Starter workspace</h3><strong>₦15,000 <small>/ month</small></strong><p>Owner dashboard, attendance, payroll, inventory, sales, and up to 10 team accounts.</p></article><label className="terms-check"><input type="checkbox" required /><span>I accept the Biz Track terms and conditions and understand that package access begins after confirmation.</span></label></div>}{step === 4 && <div className="confirmation-box"><p>Your one-time confirmation code</p><strong>{generatedCode}</strong><label><span>Enter the code above *</span><input value={code} onChange={(event) => setCode(event.target.value)} placeholder="BT-000000" /></label><small>Keep this code private. It confirms the package purchase for this workspace.</small></div>}{error && <p className="register-error">{error}</p>}<div className="register-actions"><button type="button" className="secondary-button" onClick={() => step === 1 ? onNavigate('Welcome') : setStep(step - 1)}>{step === 1 ? 'Cancel' : 'Back'}</button><button className="primary-button" type="submit">{step === 4 ? 'Confirm and create workspace' : step === 3 ? 'Continue to confirmation' : 'Continue'} <span>→</span></button></div></form></section></main></div>
}

function OffMarkPage({ members, attendance, onMark }: { members: Member[]; attendance: AttendanceEntry[]; onMark: (memberIds: number[], dates: string[]) => void }) {
  const tomorrow = new Date()
  tomorrow.setHours(0, 0, 0, 0)
  tomorrow.setDate(tomorrow.getDate() + 1)
  const firstFutureDate = tomorrow.toISOString().slice(0, 10)
  const [date, setDate] = useState(firstFutureDate)
  const [selectedDates, setSelectedDates] = useState<string[]>([firstFutureDate])
  const [selectedIds, setSelectedIds] = useState<number[]>([])
  const toggle = (id: number) => setSelectedIds((current) => current.includes(id) ? current.filter((item) => item !== id) : [...current, id])
  const addDate = () => { if (date <= today || selectedDates.includes(date)) return; setSelectedDates((current) => [...current, date].sort()) }
  const removeDate = (value: string) => setSelectedDates((current) => current.filter((item) => item !== value))
  const alreadyOff = (id: number) => selectedDates.length > 0 && selectedDates.every((value) => attendance.some((entry) => entry.memberId === id && entry.date === value && entry.status === 'Off'))
  return <><PageHeading eyebrow="PEOPLE / ATTENDANCE" title="OFF MARK" subtitle="Choose one or more future dates. Consecutive and separate days are supported." /><article className="panel member-form off-mark-panel"><div className="off-date-editor"><div><strong>Future off dates</strong><small>Only dates after today are valid.</small></div><div className="off-date-controls"><input className="filter-button" type="date" min={today} value={date} onChange={(event) => setDate(event.target.value)} /><button type="button" className="secondary-button" onClick={addDate}>Add date</button></div></div><div className="off-date-list">{selectedDates.map((value) => <span className="off-date-chip" key={value}>{value}<button type="button" aria-label={`Remove ${value}`} onClick={() => removeDate(value)}>×</button></span>)}</div><PanelHeading title="Select workers to mark off" subtitle={`${selectedIds.length} worker${selectedIds.length === 1 ? '' : 's'} selected for ${selectedDates.length} date${selectedDates.length === 1 ? '' : 's'}.`} /><div className="off-mark-list">{members.map((member) => <label className={`off-mark-worker ${selectedIds.includes(member.id) ? 'selected' : ''}`} key={member.id}><input type="checkbox" checked={selectedIds.includes(member.id)} onChange={() => toggle(member.id)} /><span className={`avatar avatar-${member.color}`}>{member.initials}</span><span><strong>{member.name}</strong><small>{member.role} · {member.department}</small></span><b>{alreadyOff(member.id) ? 'Already off' : selectedIds.includes(member.id) ? 'Selected' : 'Working'}</b></label>)}</div><div className="form-actions"><button className="primary-button" disabled={!selectedIds.length || !selectedDates.length} onClick={() => { onMark(selectedIds, selectedDates); setSelectedIds([]) }}>Mark off</button></div></article></>
}

function PermissionsPage({ members, accessByMember, setAccessByMember, onAddMember }: { members: Member[]; accessByMember: Record<number, AccessArea[]>; setAccessByMember: (value: Record<number, AccessArea[]>) => void; onAddMember: () => void }) {
  const accountMembers = members.filter((member) => member.hasAccount)
  const [selectedId, setSelectedId] = useState(accountMembers[0]?.id || 0)
  const selected = accountMembers.find((member) => member.id === selectedId)
  const granted = selected ? accessByMember[selected.id] || [] : []
  const toggle = (area: AccessArea) => { if (!selected) return; setAccessByMember({ ...accessByMember, [selected.id]: granted.includes(area) ? granted.filter((item) => item !== area) : [...granted, area] }) }
  const confirmAccess = () => { if (selected) setAccessByMember({ ...accessByMember, [selected.id]: granted }) }
  return <><PageHeading eyebrow="OWNER CONTROL / PERMISSIONS" title="Permissions" subtitle="Choose which parts of Biz Track each account holder can access." action={<button className="primary-button" onClick={onAddMember}>＋ Add account</button>} /><div className="permissions-layout"><article className="panel permissions-people"><PanelHeading title="Account holders" subtitle="Only members with login accounts appear here." />{accountMembers.length ? accountMembers.map((member) => <button key={member.id} className={`permission-person ${selectedId === member.id ? 'selected' : ''}`} onClick={() => setSelectedId(member.id)}><span className={`avatar avatar-${member.color}`}>{member.initials}</span><span><strong>{member.name}</strong><small>{member.role} · {member.department}</small></span><b>→</b></button>) : <div className="permission-empty"><strong>No account holders yet</strong><p>Enable a login account when adding a member, then return here to set their access.</p><button className="secondary-button" onClick={onAddMember}>Add account holder</button></div>}</article><article className="panel permission-editor"><PanelHeading title={selected ? `Access for ${selected.name}` : 'Choose an account'} subtitle="Select the pages this account holder can access, then confirm." />{selected ? <><div className="permission-grid">{accessAreas.map((area) => <label key={area} className={`permission-toggle ${granted.includes(area) ? 'enabled' : ''}`}><input type="checkbox" checked={granted.includes(area)} onChange={() => toggle(area)} /><span><strong>{area}</strong><small>{area === 'Overview' ? 'Business summary and daily activity' : `Open and work with ${area.toLowerCase()} records`}</small></span><i>{granted.includes(area) ? 'On' : 'Off'}</i></label>)}</div><div className="permission-confirm"><button className="primary-button" onClick={confirmAccess}>OK</button></div></> : <div className="permission-empty"><strong>Choose an account to begin</strong><p>Your access controls will appear here after you select a member with a login account.</p></div>}</article></div></>
}

function WorkspaceSidebar({ businessName, activeNav, onNavigate, onLogout }: { businessName: string; activeNav: string; onNavigate: (page: string) => void; onLogout: () => void }) {
  const links = sidebarLinks
  const iconFor = (link: string) => navItems.find((item) => item.label === link)?.icon || (link === 'Permissions' ? '⌘' : link === 'OFF MARK' ? '◉' : link === 'Team' ? '◎' : link === 'Add member' ? '+' : link === 'Settings' ? '⚙' : link === 'ROLL' ? '◷' : '◈')
  return <aside className="sidebar"><button className="brand" onClick={() => onNavigate('Overview')}><span className="brand-mark">b</span><span>{businessName}</span></button><div className="workspace-switcher"><span className="workspace-dot">{businessName.charAt(0).toUpperCase()}</span><span><strong>{businessName}</strong><small>Business workspace</small></span></div><nav aria-label="Workspace navigation">{links.map((link) => <button key={link} className={`nav-item ${activeNav === link ? 'active' : ''}`} onClick={() => onNavigate(link)}><span className="nav-icon">{iconFor(link)}</span>{link}</button>)}</nav><div className="sidebar-footer"><div className="help-mark">?</div><span>Help center</span><button className="sidebar-signout" onClick={onLogout}>↪ Sign out</button></div></aside>
}

